// SPDX-License-Identifier: MIT
pragma solidity 0.8.14;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/TFOOD.sol";

contract TFOODHighFeeTest is Test {
    TFOOD token;
    address user1 = address(0x1);
    address fakePair = address(0x123);

    // Fixed addresses from TFOOD's constructor
    address constant receiveAddress = address(0xeAC7843FC2F24ace74f7BbA228F657D0f001bE16);
    address constant fundAddress = address(0x27f5108828d66b3df802eDF021633EBb8C8d106a);
    address constant buybackAddress = address(0xA8aDDC33EBa16fc7150649521eDEf5fc33f2d0de);
    address constant routerAddress = address(0x10ED43C718714eb63d5aA57B78B54704E256024E);
    address constant fistAddress = address(0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c);

    function setUp() public {
        // Deploy token with fixed parameters
        token = new TFOOD();

        // Fund the test user from the initial receiver
        uint256 decimals = token.decimals();
        uint256 amount = 1000 * 10 ** decimals;

        // Impersonate fixed receive address to get tokens
        vm.prank(receiveAddress);
        token.transfer(user1, amount);

        // Configure contract settings
        token.setSwapPairList(fakePair, true);
        token.setFundAddress(address(this)); // Set test contract as fund receiver
    }

    function testHighFeeVulnerability() public {
        // Configure fee trigger settings
        token.setkb(2);  // Set vulnerability threshold to 2 blocks
        token.goMoon();   // Activate fee mechanism

        // Advance 1 block so we're within vulnerable range (current block < goMoonBlock + kb)
        vm.roll(block.number + 1);

        // Get transfer amounts
        uint256 amount = 100 * 10 ** token.decimals();
        uint256 expectedFee = amount * 90 / 100;
        uint256 expectedTransfer = amount - expectedFee;

        // Capture pre-transfer balances
        uint256 fundBalanceBefore = token.balanceOf(address(this));
        uint256 pairBalanceBefore = token.balanceOf(fakePair);

        // Trigger vulnerable transfer
        vm.prank(user1);
        token.transfer(fakePair, amount);

        // Verify fee application
        assertEq(
            token.balanceOf(address(this)) - fundBalanceBefore,
            expectedFee,
            "Fund should receive 90% fee"
        );
        assertEq(
            token.balanceOf(fakePair) - pairBalanceBefore,
            expectedTransfer,
            "Pair should receive remaining 10%"
        );
    }
}
